    def query(a, b):
        print(f"? {a} {b}", flush=True)
        return input().strip()

    def solve(n):
        players = list(range(1, 2*n + 1))
        top_n = []

        while len(top_n) < n:
            stack = []
            for player in players:
                while stack and query(stack[-1], player) == '<':
                    stack.pop()
                stack.append(player)
            top_n.append(stack.pop())
            players.remove(top_n[-1])

        for i in range(n):
            for j in range(i + 1, n):
                query(top_n[i], top_n[j])

        print("!", flush=True)

    t = int(input().strip())
    for _ in range(t):
        n = int(input().strip())
        solve(n)

